func testNotaFiscalNaturezaOperacaoToManyRemoveOpNfnoProcessos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a NotaFiscalNaturezaOperacao
	var b, c, d, e Processo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, notaFiscalNaturezaOperacaoDBTypes, false, strmangle.SetComplement(notaFiscalNaturezaOperacaoPrimaryKeyColumns, notaFiscalNaturezaOperacaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Processo{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, processoDBTypes, false, strmangle.SetComplement(processoPrimaryKeyColumns, processoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddNfnoProcessos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.NfnoProcessos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveNfnoProcessos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.NfnoProcessos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.NfnoID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.NfnoID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Nfno != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Nfno != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Nfno != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Nfno != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.NfnoProcessos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.NfnoProcessos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.NfnoProcessos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

