	o := NotaFiscalNaturezaOperacao{}
	if err = randomize.Struct(seed, &o, notaFiscalNaturezaOperacaoDBTypes, false); err != nil {
		t.Errorf("Unable to randomize NotaFiscalNaturezaOperacao struct: %s", err)
	}

	ctx := context.Background()
